40\u043e\u0432\u0430\u043d\u043d\u044b\u0435 CPU-\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438; (ii) \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439 \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u044b\u0439 fp64-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u0433\u0438\u043f\u0435\u0440\u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u0430 (\u0447\u0435\u0440\u0435\u0437 (X\u1d40X+\u03bbI)\u207b\u00b9), \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0449\u0438\u0439 autograd \u0432\u043e\u043e\u0431\u0449\u0435; (iii) \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e d \u0438 K, cond(X\u1d40X+\u03bbI) \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0442\u0438\u0432\u043d\u043e \u0447\u0435\u0440\u0435\u0437 SVD-\u0441\u043f\u0435\u043a\u0442\u0440. \u0411\u044d\u043d\u0447\u043c\u0430\u0440\u043a\u0438 \u0438\u0437 checkout TorchOpt (implicit diff / hypergrad / meta-learning / unfold-pack) \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435 \u0445\u0430\u0440\u043d\u0435\u0441\u0441\u044b, \u0435\u0441\u043b\u0438 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0430\u0442\u0441\u044f \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c checkout \u2014 \u043a\u0430\u043a \u0435\u0441\u0442\u044c, \u0441 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0439 \u0438\u0437\u043c\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043e\u0431\u0432\u044f\u0437\u043a\u043e\u0439; \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u044d\u043d\u0434\u043f\u043e\u0438\u043d\u0442 (\u043f.7) \u0432\u0441\u0435\u0433\u0434\u0430 \u043d\u0430 ridge-\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u0435, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0435\u0442\u044c \u043e\u0442 \u0447\u0443\u0436\u043e\u0433\u043e \u043a\u043e\u0434\u0430.\n\n## 2. Arm'\u044b\n- **A (\u043d\u0430\u0438\u0432\u043d\u044b\u0439):** `torch.autograd.grad` \u043f\u043e materialized backward-\u0433\u0440\u0430\u0444\u0443, \u0433\u0440\u0430\u0444 \u043f\u0435\u0440\u0435\u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0438\u0437 K \u0448\u0430\u0433\u043e\u0432, \u0432\u0442\u043e\u0440\u043e\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u043d\u044b\u0439 \u043e\u0431\u0445\u043e\u0434 \u043d\u0435 \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f (\u0434\u043b\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0442\u0430 \u0436\u0435 \u0444\u0430\u0437\u0430, \u0447\u0442\u043e \u0438 \u0443 B; \u0441\u043c. pre-flight).\n- **A\u2032 (\u0448\u0443\u043c\u043e\u0432\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c):** \u0431\u0430\u0439\u0442-\u0432-\u0431\u0430\u0439\u0442 \u0442\u043e\u0442 \u0436\u0435 \u043a\u043e\u0434, \u0442\u043e\u0442 \u0436\u0435 seed, \u0442\u0435 \u0436\u0435 \u0434\u0430\u043d\u043d\u044b\u0435, \u0447\u0442\u043e A, \u043d\u043e \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u043b\u043e\u0442 \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0435 \u0447\u0435\u0440\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0432\u043d\u0443\u0442\u0440\u0438 \u0431\u043b\u043e\u043a\u0430 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u043c \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u0435-\u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438. \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435: bit-identical \u0441 A. \u0414\u0432\u043e\u0439\u043d\u0430\u044f \u0444\u0443\u043d\u043a\u0446\u0438\u044f: \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u043c\u0430\u0440\u0433\u0438\u043d\u0430 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 (\u043f.5) \u0438 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0433\u0435\u0439\u0442 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c\u0430 \u0441\u0440\u0435\u0434\u044b (\u0435\u0441\u043b\u0438 A\u2260A\u2032 bitwise \u2014 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u043d\u0435\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e, \u0437\u0430\u043f\u0443\u0441\u043a \u043e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442\u0441\u044f).\n- **B (\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442 second-order):** \u0442\u043e\u0442 \u0436\u0435 \u0446\u0438\u043a\u043b \u0441 `create_graph=True` (+`retain_graph=True` \u043f\u0440\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0445 \u0434\u0438\u0444\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f\u0445) \u2014 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 hypergrad-\u043f\u0443\u0442\u044c torch.\n- **C (TorchOpt, \u0443\u0441\u043b\u043e\u0432\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f):** *functional gradient entry point of TorchOpt that avoids materializing the backward graph and reuses intermediate data; exact symbol names to be bound at implementation time against a real checkout.* \u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0438\u043c\u0451\u043d \u00ab\u0438\u0437 upstream-\u043f\u0430\u043c\u044f\u0442\u0438\u00bb \u0432 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043d\u0435\u0442; \u043e\u043d\u0438 \u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0441\u043b\u0435 binding step.\n\n**Binding step (\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u0434\u043e \u0432\u0441\u0435\u0445 \u0437\u0430\u043c\u0435\u0440\u043e\u0432, \u043f\u0440\u043e\u0442\u0438\u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e checkout; \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0445\u0435\u0448\u0435\u043c \u043a\u043e\u043c\u043c\u0438\u0442\u0430):**\n1. \u0418\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u0438\u0437\u0430\u0446\u0438\u044f API: `git rev-parse HEAD`; import-\u043f\u0430\u043a\u0435\u0442 \u2192 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0438\u0442\u044c \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0435 entry points \u043c\u043e\u0434\u0443\u043b\u044f(\u0435\u0439) diff (`inspect`/`pkgutil` + \u0447\u0442\u0435\u043d\u0438\u0435 `__init__`). \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u0442\u043e\u0447\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0438\u043c\u0451\u043d \u0432 \u043b\u043e\u0433.\n2. \u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430: `grep -rniE \"recompute|reuse|intermediate|saved|memory\" README* docs/ <pkg>/diff*` \u2014 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u043a\u0430\u043a\u043e\u0439 \u0434\u043e\u043a\u0441\u0442\u0440\u043e\u043a\u043e\u0439 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043e \u043f\u0435\u0440\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445. \u0415\u0441\u043b\u0438 \u043d\u0438 \u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430 \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u0442 \u2014 arm C \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u00ab\u043b\u044e\u0431\u043e\u0439 \u043d\u0430\u0439\u0434\u0435\u043d\u043d\u044b\u0439 functional API\u00bb, \u0430 \u0432 \u043e\u0442\u0432\u0435\u0442\u0435 \u044f\u0432\u043d\u043e \u043f\u0438\u0448\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0441\u0432\u044f\u0437\u044c \u0441 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u043e\u0439 \u043e\u0431 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0438 \u043f\u0430\u043c\u044f\u0442\u0438 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430.\n3. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e reuse \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0430\u043a\u0442\u0438\u0432\u0435\u043d: \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435 B \u0438 C; \u043e\u0431\u0445\u043e\u0434 \u0433\u0440\u0430\u0444\u0430 \u043e\u0442 \u0432\u044b\u0445\u043e\u0434\u0430 (`out.grad_fn`, `.next_functions`, \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e id) \u2014 \u0447\u0438\u0441\u043b\u043e `grad_fn`-\u0443\u0437\u043b\u043e\u0432 \u0438 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0435 \u0431\u0430\u0439\u0442\u044b \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 saved_tensors; \u043f\u043b\u044e\u0441 `torch.profiler(profile_memory=True)` \u043d\u0430 \u0444\u0430\u0437\u0443 bwd. \u0415\u0441\u043b\u0438 \u0443 C \u0433\u0440\u0430\u0444 \u0438 saved-\u0431\u0430\u0439\u0442\u044b \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b B \u2192 reuse \u043c\u043e\u043b\u0447\u0430 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d/\u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2192 veto.\n4. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043e\u0434\u043d\u043e\u0433\u043e \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043e\u0431\u044a\u0435\u043a\u0442\u0430: \u0433\u0438\u043f\u0435\u0440\u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u044b B \u0438 C \u0432 fp64 \u043d\u0430 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0439 \u0442\u043e\u0447\u043a\u0435 \u0441\u0435\u0442\u043a\u0438; \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 relative L2 < 1e-10, \u0438\u043d\u0430\u0447\u0435 veto.\n5. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0430 \u0441\u043a\u0440\u044b\u0442\u044b\u0439 fallback: monkeypatch-\u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0432\u044b\u0437\u043e\u0432\u043e\u0432 `torch.autograd.grad` \u0441 `create_graph=True` \u0432\u043d\u0443\u0442\u0440\u0438 \u0432\u044b\u0437\u043e\u0432\u0430 C; \u043d\u0435\u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043b\u043e\u0433 \u043a\u0430\u043a \u00abC \u0434\u0435\u043b\u0435\u0433\u0438\u0440\u0443\u0435\u0442 \u0432 standard second-order\u00bb.\n\n**Veto-\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439:** \u043f\u0440\u043e\u0432\u0430\u043b \u0448\u0430\u0433\u0430 1 (\u043d\u0435\u0442 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e functional diff entry point) \u0438\u043b\u0438 \u0448\u0430\u0433\u0430 3/4 \u2192 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u043c: \u043e\u0442\u0432\u0435\u0442 \u00ab\u043d\u0435 \u043c\u043e\u0436\u0435\u043c \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c \u0432 \u044d\u0442\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438\u00bb, \u043d\u0435 \u00abTorchOpt \u043d\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442\u00bb \u0438 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442.\n\n**Pre-flight (\u0434\u043e \u0437\u0430\u043c\u0435\u0440\u043e\u0432):** A \u0438 B \u0441\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0431\u043e\u0439 \u0432 fp64; \u043e\u0431\u0430 \u0441\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u0441 \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u043e\u0439 \u0444\u043e\u0440\u043c\u043e\u0439; C \u2014 \u0441 B (\u0448\u0430\u0433 4). \u0418\u043d\u0430\u0447\u0435 \u0434\u0430\u043b\u044c\u0448\u0435 \u043d\u0435 \u0438\u0434\u0451\u043c.\n\n## 3. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n**\u0412\u0440\u0435\u043c\u044f (T1):** wall-clock `perf_counter` \u043d\u0430 \u0432\u0435\u0441\u044c hypergrad-\u0448\u0430\u0433 \u0438 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u043e fwd/bwd; 5 warmup + 31 \u0437\u0430\u043c\u0435\u0440 \u043d\u0430 arm \u0432 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438; \u043c\u0435\u0434\u0438\u0430\u043d\u0430+IQR.\n\n**\u041f\u0430\u043c\u044f\u0442\u044c \u2014 primary/\u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435 (\u043f\u043e \u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u044e 5):**\n- **M1 (PRIMARY):** \u043f\u0438\u043a \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0445 \u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445: \u0447\u0438\u0441\u043b\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 saved_tensors \u0438 \u0438\u0445 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0435 \u0431\u0430\u0439\u0442\u044b, \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u043d\u044b\u0435 (\u0430) \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044f \u0433\u0440\u0430\u0444\u0430 \u0438 (\u0431) \u043d\u0430 \u043f\u0438\u043a\u0435 bwd \u0447\u0435\u0440\u0435\u0437 registry \u043d\u0430 saved_tensors; \u0438\u043c\u0435\u043d\u043d\u043e M1 \u0441\u0432\u044f\u0437\u0430\u043d \u0441 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u043e\u0439 reuse \u0438 \u0438\u043c\u0435\u043d\u043d\u043e \u043f\u043e \u043d\u0435\u043c\u0443 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430.\n- M2 (\u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044e\u0449\u0430\u044f): \u043f\u0440\u0438\u0440\u043e\u0441\u0442 \u043f\u0438\u043a\u0430 RSS (VmHWM) \u0441\u0432\u0435\u0436\u0435\u0433\u043e \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u0430 \u0432\u043e\u043a\u0440\u0443\u0433 \u0441\u0435\u043a\u0446\u0438\u0438 \u2014 \u0441 \u044f\u0432\u043d\u043e\u0439 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439, \u0447\u0442\u043e \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043e\u0432\u0435\u0440\u0445\u0435\u0434 CPU-\u0430\u043b\u043b\u043e\u043a\u0430\u0442\u043e\u0440\u0430 torch \u0438 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044e, \u0442.\u0435. \u043d\u0435 \u0435\u0441\u0442\u044c \u00ab\u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435\u00bb \u0432 \u0447\u0438\u0441\u0442\u043e\u043c \u0432\u0438\u0434\u0435.\n- M3 (\u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f): tracemalloc peak \u043a\u0430\u043a python-\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u044b\u0439 proxy.\n\u0420\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e M1; \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 M1 \u0441 M2/M3 \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0430\u043b\u043b\u043e\u043a\u0430\u0442\u043e\u0440\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442, \u0430 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435/\u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0435 reuse.\n\n**\u0427\u0438\u0441\u043b\u0435\u043d\u043d\u0430\u044f \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u2014 \u043f\u0440\u0435\u0434\u6ce8\u518c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 \u043f\u043e\u0440\u043e\u0433\u0438 (\u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430, \u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 2):**\n\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u043c rel_err(arm) = \u2016g_fp32(arm) \u2212 g_fp64(\u0442\u043e\u0442 \u0436\u0435 arm)\u2016\u2082 / \u2016g_fp64\u2016\u2082.\n- **S1 (\u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f):** \u043d\u0430 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0439 \u0442\u043e\u0447\u043a\u0435 \u0441\u0435\u0442\u043a\u0438 paired bootstrap 95% CI \u043d\u0430 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u043c\u0435\u0434\u0438\u0430\u043d rel_err(C) \u2212 rel_err(B). Non-inferiority: CI upper \u2264 0. \u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u00abC \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0435\u0435\u00bb \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 CI upper < 0 \u0441\u0442\u0440\u043e\u0433\u043e (X=0, superiority \u0442\u0440\u0435\u0431\u0443\u0435\u0442 CI, \u043d\u0435 \u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u044e\u0449\u0435\u0433\u043e 0; \u0437\u0435\u0440\u043a\u0430\u043b\u044c\u043d\u043e \u0434\u043b\u044f C vs A).\n- **S2:** \u043d\u0430\u043a\u043b\u043e\u043d log2(rel_err) vs log2(K) (OLS \u043f\u043e K\u2208{5,10,20,50,100} \u043f\u0440\u0438 d=1k). \u00abC \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0435\u0435 \u043f\u043e \u0433\u043b\u0443\u0431\u0438\u043d\u0435\u00bb iff 95% bootstrap CI \u043d\u0430\u043a\u043b\u043e\u043d\u0438 C \u0438 B \u043d\u0435 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0438 \u043d\u0430\u043a\u043b\u043e\u043d C \u043c\u0435\u043d\u044c\u0448\u0435. \u041e\u0442\u043c\u0435\u0447\u0430\u044e \u0447\u0435\u0441\u0442\u043d\u043e: \u043d\u0435\u043f\u0435\u0440\u0430\u043a\u0440\u044b\u0442\u0438\u0435 \u0434\u0432\u0443\u0445 CI \u2014 \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u0435\u0435 \u043f\u0430\u0440\u043d\u043e\u0433\u043e \u0442\u0435\u0441\u0442\u0430; \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u043a\u0430\u043a \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e.\n- **S3:** breakdown fraction \u2014 \u0434\u043e\u043b\u044f \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u0441 NaN/Inf \u0438\u043b\u0438 \u2016g_arm\u2016/\u2016g_fp64\u2016 \u2209 [0.5, 2] \u043d\u0430 \u0441\u0435\u0442\u043a\u0435 cond\u2208{1e2,1e4,1e6,1e8} (X \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 SVD \u0441 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u043c \u0441\u043f\u0435\u043a\u0442\u0440\u043e\u043c, \u03bb \u043f\u043e\u0434\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0434 \u0446\u0435\u043b\u0435\u0432\u043e\u0435 cond). Arm \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u043c \u043f\u0440\u0438 fraction > 0.05. \u00abC \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0435\u0435 \u043f\u0440\u0438 \u043f\u043b\u043e\u0445\u043e\u0439 \u043e\u0431\u0443\u0441\u043b\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438\u00bb iff \u043d\u0430 cond=1e6 CI \u043d\u0430 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c fraction (paired bootstrap) upper < 0.\n- \u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c-\u0433\u0435\u0439\u0442: A vs A\u2032 bitwise \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438; \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u2192 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0438 \u0434\u0438\u0430\u0433\u043d\u043e\u0437 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442.\n\n## 4. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044b (\u0437\u0430\u0445\u0430\u0440\u0434\u043a\u043e\u0436\u0435\u043d\u043e \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u043c \u043c\u0435\u0436\u0434\u0443 \u0432\u0441\u0435\u043c\u0438 arm'\u0430\u043c\u0438)\n\u0412\u0435\u0440\u0441\u0438\u044f/\u0441\u0431\u043e\u0440\u043a\u0430 torch \u0438 git-hash torchopt; dtype fp32 (fp64 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043e\u0432); \u043e\u0434\u0438\u043d \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u0434\u0430\u043d\u043d\u044b\u0445 \u2192 \u043e\u0434\u043d\u0438 \u0438 \u0442\u0435 \u0436\u0435 \u0442\u0435\u043d\u0437\u043e\u0440\u044b X, y, \u03bb \u043d\u0430 \u0432\u0441\u0435 arm'\u044b; \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 K, d, cond; `torch.set_num_threads(1)`, `OMP_NUM_THREADS=1`, `MKL_NUM_THREADS=1`, \u0437\u0430\u043f\u0443\u0441\u043a `taskset` \u043d\u0430 \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u043d\u043e\u0435 \u044f\u0434\u0440\u043e (\u0438\u043d\u0430\u0447\u0435 224 \u044f\u0434\u0440\u0430 \u0441\u044a\u0435\u0434\u0430\u044e\u0442 \u044d\u0444\u0444\u0435\u043a\u0442); \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u043d\u0443\u0442\u0440\u0438 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u2014 \u0431\u043b\u043e\u043a\u0438, \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0431\u043b\u043e\u043a\u0435 arm'\u044b \u0438\u0434\u0443\u0442 round-robin \u0441 \u0440\u043e\u0442\u0430\u0446\u0438\u0435\u0439 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0430 \u043f\u043e \u0431\u043b\u043e\u043a\u0430\u043c (\u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 order bias; \u0442\u0440\u0435\u043d\u0438\u0435/\u0442\u0435\u043f\u043b\u043e\u0432\u043e\u0439 \u0434\u0440\u0435\u0439\u0444 \u043f\u043e\u0433\u043b\u043e\u0449\u0430\u044e\u0442\u0441\u044f \u043c\u0435\u0434\u0438\u0430\u043d\u043e\u0439 \u0438 \u0447\u0435\u0440\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435\u043c); \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 warmup (5) \u0438 \u0447\u0438\u0441\u043b\u043e \u0437\u0430\u043c\u0435\u0440\u043e\u0432 (31); \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f = \u0441\u0432\u0435\u0436\u0438\u0439 subprocess (\u0447\u0438\u0441\u0442\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0430\u043b\u043b\u043e\u043a\u0430\u0442\u043e\u0440\u0430); `allow_tf32=False` (\u043d\u0430 CPU no-op, \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u0438).\n**\u0424\u043b\u0430\u0433 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u2014 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e (\u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 7):** `torch.use_deterministic_algorithms(True)` \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u0432\u0441\u0435\u0445 arm'\u043e\u0432: \u0432\u0441\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044f (matmul/add/solve/sum) \u043e\u0434\u043d\u043e\u043f\u043e\u0442\u043e\u0447\u043d\u043e \u043d\u0430 CPU \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u044b, \u0430 \u0444\u043b\u0430\u0433 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043b\u044e\u0431\u043e\u0435 \u0441\u043a\u0440\u044b\u0442\u043e\u0435 \u043d\u0435\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u044f\u0434\u0440\u043e \u0432 \u044f\u0432\u043d\u0443\u044e \u043e\u0448\u0438\u0431\u043a\u0443 \u0432\u043c\u0435\u0441\u0442\u043e \u0442\u0438\u0445\u043e\u0433\u043e \u0448\u0443\u043c\u0430. \u041f\u0440\u0435\u0434\u6ce8\u518c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 fallback: \u0435\u0441\u043b\u0438 \u043a\u0430\u043a\u043e\u0439-\u043b\u0438\u0431\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u0431\u0440\u043e\u0441\u0430\u0435\u0442 \u00abnot deterministic\u00bb \u2014 \u0444\u043b\u0430\u0433 \u0432\u044b\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043d\u043e \u0434\u043b\u044f \u0432\u0441\u0435\u0445 arm'\u043e\u0432, \u0438 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0433\u0435\u0439\u0442\u043e\u043c A/A\u2032 bitwise + \u043e\u0434\u043d\u043e\u043f\u043e\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c\u044e. \u041f\u0440\u0430\u0432\u0438\u043b\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0441\u0435\u0439\u0447\u0430\u0441, \u0430 \u043d\u0435 \u00ab\u0440\u0435\u0448\u0438\u0442\u0441\u044f \u043f\u043e\u0442\u043e\u043c\u00bb.\n\n## 5. \u041c\u0430\u0440\u0433\u0438\u043d \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u2014 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d \u043a \u043d\u0443\u043b\u0435\u0432\u043e\u043c\u0443 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044e (\u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 3)\n\u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u043a\u0440\u0443\u0433\u043b\u044b\u0445 \u0447\u0438\u0441\u0435\u043b \u0438\u0437 \u0433\u043e\u043b\u043e\u0432\u044b. \u041d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u03b4 = |median(T_A) \u2212 median(T_A\u2032)| / median(T_A). \u041c\u0430\u0440\u0433\u0438\u043d **m = max( 2 \u00d7 median_r\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0439(\u03b4), 0.05 ) \u0441 \u043f\u043e\u0442\u043e\u043b\u043a\u043e\u043c 0.20**. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435: 2\u00d7 \u0440\u0430\u0437\u0431\u0440\u043e\u0441\u0430 \u043d\u0443\u043b\u0435\u0432\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u2248 \u0433\u0440\u0443\u0431\u0430\u044f 2\u03c3-\u043e\u0446\u0435\u043d\u043a\u0430 \u0448\u0443\u043c\u0430 \u00ab\u0442\u043e\u0442 \u0436\u0435 \u043a\u043e\u0434 \u0432 \u0434\u0440\u0443\u0433\u043e\u043c \u0441\u043b\u043e\u0442\u0435/\u043f\u0440\u043e\u0446\u0435\u0441\u0441\u0435\u00bb; floor 5% \u043d\u0435 \u0434\u0430\u0451\u0442 \u043e\u0431\u044a\u044f\u0432\u0438\u0442\u044c \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0435 \u043e\u043a\u043d\u043e \u043d\u0430 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0442\u0438\u0445\u043e\u0439 \u043c\u0430\u0448\u0438\u043d\u0435; ceiling 20% \u0437\u0430\u043f\u0440\u0435\u0449\u0430\u0435\u0442 \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e \u0448\u0438\u0440\u043e\u043a\u043e\u0435 \u043e\u043a\u043d\u043e. \u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u03b4 \u043d\u0430 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u043e\u043c \u044f\u0434\u0440\u0435 \u2014 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043e\u0432, \u043d\u043e \u044d\u0442\u043e \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u043f\u0438\u043b\u043e\u0442\u0430, \u0430 \u043d\u0435 \u0432\u0445\u043e\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430: \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043f\u0440\u0438 \u043b\u044e\u0431\u043e\u043c \u03b4. \u042d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u2014 TOST: \u00ab\u043d\u0435\u0442 \u0440\u0430\u0437\u043d\u0438\u0446\u044b\u00bb iff bootstrap CI \u043d\u0430 paired median ratio T_C/T_B \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u0432\u043d\u0443\u0442\u0440\u0438 [1\u2212m, 1+m]; \u00ab\u0431\u044b\u0441\u0442\u0440\u0435\u0435/\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435\u00bb iff CI \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u0441\u043d\u0430\u0440\u0443\u0436\u0438.\n\n## 6. \u0421\u0435\u0442\u043a\u0430, \u0431\u044e\u0434\u0436\u0435\u0442, fallback (\u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 5)\n\u0420\u0435\u0448\u0451\u0442\u043a\u0430: d\u2208{128, 1k, 8k} \u00d7 K\u2208{5,10,20,50,100}; cond-\u0441\u0442\u0440\u0435\u0441\u0441 {1e2,1e4,1e6,1e8} \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e\u0439 \u043f\u043e\u043b\u043e\u0441\u0435. Runtime-\u0431\u044e\u0434\u0436\u0435\u0442 \u0432 \u0437\u0430\u0434\u0430\u0447\u0435 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e \u043a\u0430\u043a \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0435. \u041f\u043e\u043b\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f: \u0432\u0440\u0435\u043c\u044f/\u043f\u0430\u043c\u044f\u0442\u044c \u043f\u043e \u0432\u0441\u0435\u043c 15 \u0442\u043e\u0447\u043a\u0430\u043c d\u00d7K; \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c: K-\u0441\u0432\u0438\u043f \u043f\u0440\u0438 d=1k (5 \u0442\u043e\u0447\u0435\u043a) + cond-\u0441\u0432\u0438\u043f \u043f\u0440\u0438 (d=1k, K=20) (4 \u0442\u043e\u0447\u043a\u0438). \u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c: 4 arm'\u0430 \u00d7 3 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u00d7 (5+31) \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u00d7 \u0447\u0438\u0441\u043b\u043e \u0442\u043e\u0447\u0435\u043a; \u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u2248 36 \u0442\u043e\u0447\u0435\u043a \u00d7 4 \u00d7 3 \u00d7 36 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u0432 + \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043d\u044b\u0435 fp64-\u043f\u0440\u043e\u0433\u043e\u043d\u044b \u2248 ~15.5 \u0442\u044b\u0441. \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432. \u0424\u043e\u0440\u043c\u0443\u043b\u0430 \u043e\u0446\u0435\u043d\u043a\u0438: T_total \u2248 N_cells \u00d7 N_arms \u00d7 (R+Q)\u00b7R\u207b\u00b9\u2026 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u0435\u0435 \u044f\u0432\u043d\u043e: T_total \u2248 3 \u00d7 \u03a3_cells \u03a3_arms (36/31)\u00b7T_cell \u00d7 1.3 (overhead \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0432), \u0433\u0434\u0435 T_cell \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435. **\u041f\u0438\u043b\u043e\u0442-\u043f\u0440\u0430\u0432\u0438\u043b\u043e:** \u0438\u0437\u043c\u0435\u0440\u0438\u0442\u044c T_cell \u043d\u0430 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0439 \u0442\u043e\u0447\u043a\u0435; \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 T_total > \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0433\u043e \u043e\u043a\u043d\u0430 \u2014 fallback-\u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f: \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u0442\u043e\u0447\u043a\u0430 + K-\u0441\u0432\u0438\u043f \u043f\u0440\u0438 d=1k + d-\u0441\u0432\u0438\u043f \u043f\u0440\u0438 K=20 (13 \u0442\u043e\u0447\u0435\u043a), cond-\u0441\u0432\u0438\u043f \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0434\u043e {1e4,1e6,1e8}, \u043f\u043e\u0432\u0442\u043e\u0440\u044b 31\u219215, \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 3\u21922. \u041f\u043e\u043b\u043d\u0430\u044f vs fallback \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0444\u0430\u0437\u044b \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043f\u0438\u043b\u043e\u0442\u0430 \u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f.\n\n## 7. \u0410\u043d\u0430\u043b\u0438\u0437 \u0438 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u044d\u043d\u0434\u043f\u043e\u0438\u043d\u0442 (\u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 6)\n\u0412\u0441\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043f\u0430\u0440\u043d\u044b\u0435: \u0432\u043d\u0443\u0442\u0440\u0438 \u0431\u043b\u043e\u043a\u0430/\u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 arm'\u044b \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0442 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0438 seed; \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u0438\u0437 paired-\u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0435\u0439 \u043f\u043e \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c (bootstrap \u043f\u043e \u0438\u043d\u0434\u0435\u043a\u0441\u0430\u043c \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432, \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0449\u0438\u0439 \u043f\u0430\u0440\u043d\u043e\u0441\u0442\u044c) \u0441 \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u0435\u0439 \u043f\u043e \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f\u043c.\n**\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u044d\u043d\u0434\u043f\u043e\u0438\u043d\u0442 (\u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439, pre-registered):** \u0432\u0440\u0435\u043c\u044f hypergrad-\u0448\u0430\u0433\u0430, \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u043c\u0435\u0434\u0438\u0430\u043d T_C/T_B \u043d\u0430 \u0442\u043e\u0447\u043a\u0435 (d=1k, K=20, cond=1e4), TOST \u043f\u0440\u043e\u0442\u0438\u0432 \u043c\u0430\u0440\u0433\u0438\u043d\u0430 m (\u043f.5). \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f-\u043f\u043e-\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438 (pre-registered secondary #1): S1 rel_err C\u2212B \u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0442\u043e\u0447\u043a\u0435. \u0412\u0441\u0451 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 (\u0432\u0441\u044f \u0440\u0435\u0448\u0451\u0442\u043a\u0430, S2, S3, M1\u2013M3, \u0447\u0443\u0436\u0438\u0435 \u0445\u0430\u0440\u043d\u0435\u0441\u0441\u044b) \u2014 exploratory: \u0441\u043e\u043e\u0431\u0449\u0430\u044e\u0442\u0441\u044f effect sizes \u0441 CI, \u0431\u0435\u0437 family-wise-\u043f\u0440\u0438\u0442\u044f\u0437\u0430\u043d\u0438\u0439; \u0434\u043b\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u00abS2 \u043d\u0430 K-\u0441\u0432\u0438\u043f\u0435\u00bb \u2014 Holm-Bonferroni. \u041f-hacking \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0434\u0435\u043a\u043b\u0430\u0440\u0430\u0446\u0438\u0435\u0439: \u043d\u0438 \u043e\u0434\u043d\u0430 \u0442\u043e\u0447\u043a\u0430 \u043d\u0435 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u0432 primary post hoc.\n\n## 8. \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u043e\u0441\u0442\u0438 (\u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u043c \u043f\u0443\u043d\u043a\u0442\u043e\u043c, \u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 4)\n\u0412\u044b\u0432\u043e\u0434\u044b \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0438 \u043f\u0430\u043c\u044f\u0442\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 \u0434\u043b\u044f CPU-only fp32 \u043f\u0440\u0438 \u043e\u0434\u043d\u043e\u043f\u043e\u0442\u043e\u0447\u043d\u043e\u043c \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u043e\u043c \u044f\u0434\u0440\u0435. \u041d\u0430 GPU \u043d\u0435 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u044f\u0442\u0441\u044f: (i) \u0442\u0430\u043c \u0434\u0440\u0443\u0433\u043e\u0439 \u0430\u043b\u043b\u043e\u043a\u0430\u0442\u043e\u0440 (caching), \u0441\u0432\u043e\u0438 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043f\u0438\u043a\u0430 (`max_memory_allocated`/`reserved`), \u0438 M2-RSS \u0432\u043e\u043e\u0431\u0449\u0435 \u043d\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c; (ii) \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u044f \u0430\u043b\u043b\u043e\u043a\u0430\u0446\u0438\u0439 \u043d\u0430 CPU \u0438\u043c\u0435\u0435\u0442 \u0434\u0440\u0443\u0433\u0443\u044e \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0446\u0435\u043d\u0443 (\u043d\u0435\u0442 kernel launch overhead, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0430 GPU \u0447\u0430\u0441\u0442\u043e \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u0435\u0442) \u2014 \u0437\u043d\u0430\u043a \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043d\u0430 GPU \u0434\u0430\u043d\u043d\u044b\u043c \u0434\u0438\u0437\u0430\u0439\u043d\u043e\u043c \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f; (iii) \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c-\u0444\u043b\u0430\u0433 \u0438 \u043d\u0435\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 GPU-\u0440\u0435\u0434\u0443\u043a\u0446\u0438\u0438 \u043c\u0435\u043d\u044f\u044e\u0442 \u043a\u0430\u0440\u0442\u0438\u043d\u0443 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438. GPU-\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442, \u043d\u0435 \u044d\u0442\u043e\u0442.\n\n## 9. \u0427\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0434\u0438\u0437\u0430\u0439\u043d (\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0438\u0441\u0445\u043e\u0434)\n\u041a\u0430\u0436\u0434\u044b\u0439 \u0438\u0441\u0445\u043e\u0434 \u2014 \u043e\u0442\u0432\u0435\u0442: (1) C \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u043f\u0440\u0438 M1-\u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0438 \u0438 rel_err \u043d\u0435 \u0445\u0443\u0436\u0435 \u2192 \u00ab\u0434\u0430\u00bb \u043f\u043e \u043e\u0431\u0435\u0438\u043c \u043e\u0441\u044f\u043c; (2) M1 \u043d\u0438\u0436\u0435, \u0432\u0440\u0435\u043c\u044f \u0432 TOST-\u043e\u043a\u043d\u0435 \u2192 \u00ab\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u044f \u043f\u0430\u043c\u044f\u0442\u0438 \u0435\u0441\u0442\u044c, \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u044f \u043d\u0435\u0442\u00bb; (3) rel_err CI \u0432\u044b\u0448\u0435 0 \u2192 \u00ab\u043c\u0435\u043d\u0435\u0435 \u0441\u0442\u0430\u0431\u0438\u043b\u0435\u043d\u00bb; (4) \u0432\u0441\u0451 \u0432 \u043e\u043a\u043d\u0430\u0445 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u2192 \u00ab\u043d\u0435\u0442\u00bb; (5) veto \u043d\u0430 binding \u2192 \u00ab\u043d\u0435 \u043c\u043e\u0436\u0435\u043c \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c\u00bb. \u041d\u0438\u0447\u0442\u043e \u0438\u0437 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c \u0438\u0441\u0445\u043e\u0434\u043e\u043c \u0437\u0430\u0440\u0430\u043d\u0435\u0435.", "evidence": "[\"\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f (\u0444\u0430\u043a\u0442, \u0440\u0430\u043d\u0435\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0430): /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json; find \u043f\u043e / \u043d\u0430 *torchopt* \u043f\u0443\u0441\u0442; import torch -> ModuleNotFoundError; site-packages \u043f\u0443\u0441\u0442; Python 3.14.4; nproc=224; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430; GPU \u043e\u0442\u043a\u043b\u044e\u0447\u0451\u043d \u2014 \u043e\u0442\u0441\u044e\u0434\u0430 \u0440\u0430\u0437\u0434\u0435\u043b 0 \u043e \u043d\u0435\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u043c \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0435\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 1 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f (arm C \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d) \u0437\u0430\u043a\u0440\u044b\u0442: \u0443\u0441\u043b\u043e\u0432\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f C + binding step \u0438\u0437 5 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0445 \u0448\u0430\u0433\u043e\u0432 (\u0438\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u0438\u0437\u0430\u0446\u0438\u044f API \u0441 git-hash, grep-\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430 reuse \u0432 \u0434\u043e\u043a\u0443\u043f\u0430\u0445 checkout, \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0433\u0440\u0430\u0444\u0430/saved_tensors B vs C \u043d\u0430 \u0432\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u043e\u0441\u0442\u044c reuse, fp64-\u0441\u0432\u0435\u0440\u043a\u0430 B/C < 1e-10 \u043d\u0430 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043e\u0431\u044a\u0435\u043a\u0442\u0430, monkeypatch-\u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0441\u043a\u0440\u044b\u0442\u043e\u0433\u043e create_graph fallback) + \u044f\u0432\u043d\u044b\u0439 veto-\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00ab\u043d\u0435 \u043c\u043e\u0436\u0435\u043c \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c\u00bb\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 2 (\u043f\u043e\u0440\u043e\u0433\u0438) \u0437\u0430\u043a\u0440\u044b\u0442\u043e \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u043c\u0438 \u043f\u0440\u0435\u0434\u6ce8\u518c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438: S1 non-inferiority CI upper \u2264 0 / superiority \u043f\u0440\u0438 CI upper < 0; S2 \u2014 \u043d\u0435\u043f\u0435\u0440\u0430\u043a\u0440\u044b\u0442\u0438\u0435 bootstrap CI \u043d\u0430\u043a\u043b\u043e\u043d\u043e\u0432; S3 \u2014 fraction NaN/Inf \u0438\u043b\u0438 norm-ratio \u0432\u043d\u0435 [0.5,2] > 0.05 = \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f, \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430 cond=1e6\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 3 (\u043c\u0430\u0440\u0433\u0438\u043d) \u0437\u0430\u043a\u0440\u044b\u0442\u043e: \u0432\u0432\u0435\u0434\u0451\u043d arm A' (\u0431\u0438\u0442-\u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 A, \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u043b\u043e\u0442/\u043f\u0440\u043e\u0446\u0435\u0441\u0441), m = max(2\u00d7median \u03b4(A,A\u2032), 0.05) \u0441 ceiling 0.20, TOST-\u043f\u0440\u0430\u0432\u0438\u043b\u043e; \u043a\u0440\u0443\u0433\u043b\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u00b110% \u0438\u0437 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0430 \u0438\u0437\u044a\u044f\u0442\u043e\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 4 (\u043f\u0430\u043c\u044f\u0442\u044c) \u0437\u0430\u043a\u0440\u044b\u0442\u043e: primary = M1 (\u043f\u0438\u043a \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0445 saved_tensors \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u0438 \u0431\u0430\u0439\u0442\u0430\u043c, \u043e\u0431\u0445\u043e\u0434 grad_fn-\u0433\u0440\u0430\u0444\u0430 + profiler), M2 VmHWM \u0438 M3 tracemalloc \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435; \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430 \u043d\u0430 GPU \u0432\u044b\u043d\u0435\u0441\u0435\u043d\u044b \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0430\u0437\u0434\u0435\u043b 8\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 5 (\u0431\u044e\u0434\u0436\u0435\u0442): \u0441\u0435\u0442\u043a\u0430 15 \u0442\u043e\u0447\u0435\u043a d\u00d7K + 9 \u0442\u043e\u0447\u0435\u043a \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u2248 36 \u0442\u043e\u0447\u0435\u043a, ~15.5 \u0442\u044b\u0441. \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043a\u043e\u043d\u0444\u0438\u0433\u0435 (\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430 \u043e\u0442 4 arm'\u043e\u0432 \u00d7 3 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u00d7 36 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043d\u0430 \u0442\u043e\u0447\u043a\u0443); runtime-\u0431\u044e\u0434\u0436\u0435\u0442 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d \u043a\u0430\u043a \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0435 \u0437\u0430\u0434\u0430\u0447\u0438; \u0434\u0430\u043d\u043e \u043f\u0438\u043b\u043e\u0442-\u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0438 \u0443\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u0439 fallback (13 \u0442\u043e\u0447\u0435\u043a, 15 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432, 2 \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438)\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 6 (\u0430\u043d\u0430\u043b\u0438\u0437): \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 pre-registered primary endpoint (T_C/T_B \u043d\u0430 d=1k, K=20, cond=1e4, TOST), paired-\u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u043e \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c/\u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f\u043c, exploratory-\u0441\u0442\u0430\u0442\u0443\u0441 \u0440\u0435\u0448\u0451\u0442\u043a\u0438, Holm-Bonferroni \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e\u0433\u043e \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430\", \"\u0417\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 7 (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c): \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u2014 use_deterministic_algorithms(True) \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e \u0441 \u043f\u0440\u0435\u0434\u6ce8\u518c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c fallback-\u043f\u0440\u0430\u0432\u0438